import{_ as t,o,c as r,a2 as d}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"OAuth 2.1 Provider Dogfood — endpoints-skeleton quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/oauth21-provider-endpoints.md","filePath":"quality-reports/auth/oauth21-provider-endpoints.md"}'),i={name:"quality-reports/auth/oauth21-provider-endpoints.md"};function s(a,e,n,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="oauth-2-1-provider-dogfood-—-endpoints-skeleton-quality-report" tabindex="-1">OAuth 2.1 Provider Dogfood — endpoints-skeleton quality report <a class="header-anchor" href="#oauth-2-1-provider-dogfood-—-endpoints-skeleton-quality-report" aria-label="Permalink to &quot;OAuth 2.1 Provider Dogfood — endpoints-skeleton quality report&quot;">​</a></h1><p>Skeleton report for <code>examples/dogfood-oauth21-provider</code> Sub-Issue #864 (v1.21-3a).</p><p>Full mock vs real fidelity numbers are filled in as PKCE / DPoP / refresh rotation / revocation cascade land in Sub-Issues #865 - #867. This report tracks the endpoints-skeleton phase only — the 5 RFC 9700 endpoints exist and enforce the OAuth 2.1 hardening rules, but PKCE / DPoP / rotation logic is delegated to the underlying kiwa AS.</p><h2 id="fidelity-axes-endpoints-skeleton" tabindex="-1">Fidelity axes (endpoints-skeleton) <a class="header-anchor" href="#fidelity-axes-endpoints-skeleton" aria-label="Permalink to &quot;Fidelity axes (endpoints-skeleton)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>mock (<code>@kiwa/auth</code>)</th><th>real (oauth2-mock-server + testcontainers)</th><th>assertion</th></tr></thead><tbody><tr><td>1. discovery metadata</td><td>Static shape derived from <code>issuer</code>; response_types=[code], grant_types=[authorization_code, refresh_token], code_challenge_methods=[S256], dpop_signing_alg_values=[ES256], token_endpoint_auth_methods=[client_secret_basic, client_secret_post, none]</td><td>oauth2-mock-server emits an identical shape at container boot; issuer is derived from <code>OAUTH2_ISSUER</code> env var Sub-Issue #865 will set</td><td>RFC 8414 §2 mandatory keys present; RFC 9700 restrictions honoured (implicit + password + plain PKCE explicitly omitted).</td></tr><tr><td>2. <code>/authorize</code> OAuth 2.1 hardening</td><td><code>response_type=token</code> → 400 <code>unsupported_response_type</code>; <code>code_challenge_method=plain</code> → 400 <code>invalid_request</code>; missing <code>state</code> → surfaces via AS reject (Sub-Issue #865 adds explicit <code>invalid_request</code> mapping); valid <code>code</code> + <code>S256</code> → 302 with <code>code</code> + <code>state</code> in query</td><td>oauth2-mock-server rejects <code>response_type=token</code> with the same code; testcontainers image built from <code>oauth2-mock-server@8</code> covers RFC 9700 §2.1</td><td>Both drivers refuse implicit + plain PKCE with the same status + error code so a client cannot mismatch discovery + runtime.</td></tr><tr><td>3. <code>/token</code> grant allowlist</td><td><code>grant_type=password</code> → 400 <code>unsupported_grant_type</code>; <code>grant_type=client_credentials</code> → 400; <code>grant_type=authorization_code</code> + PKCE verifier → 200 with <code>access_token</code> + <code>refresh_token</code> + <code>token_type=Bearer</code> + <code>expires_in=3600</code></td><td>oauth2-mock-server refuses the same grants + returns the RFC 6749 §5.1 body shape</td><td>RFC 9700 §2 grant allowlist enforcement — the mock rejects at the AS layer, the real driver rejects at the HTTP layer. Fidelity axis diffs on error code + shape.</td></tr><tr><td>4. <code>/revoke</code> + <code>/introspect</code> contract</td><td>Revoke of unknown → 200 (RFC 7009 §2.2 idempotency); Introspect unknown → <code>{active: false}</code>; Revoke of active → Introspect flips to <code>active: false</code> with <code>client_id</code> + <code>sub</code> still populated on the pre-revoke response</td><td>oauth2-mock-server implements both RFCs identically</td><td>Revocation state observable through introspection.</td></tr></tbody></table><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>tests/endpoints-skeleton.spec.ts</code> — 15 tests, split into five describe blocks: <ul><li><code>axis 1 — discovery metadata</code> — 2 tests covering the mandatory RFC 8414 §2 shape + the OAuth 2.1 exclusions.</li><li><code>axis 2 — /authorize OAuth 2.1 hardening</code> — 3 tests covering implicit refuse + plain PKCE refuse + valid code path.</li><li><code>axis 3 — /token grant allowlist</code> — 3 tests covering password refuse + client_credentials refuse + valid PKCE exchange.</li><li><code>axis 4 — /revoke + /introspect contract</code> — 3 tests covering revoke idempotency + introspect sentinel + revoke -&gt; introspect state flip.</li><li><code>real adapter — env-missing skeleton</code> — 4 tests validating <code>KIWA_OAUTH21_ENV_MISSING</code> gate + <code>KIWA_MODE=mock</code> override + refusal + discovery-still-works.</li></ul></li></ul><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — forces the mock adapter; every test always runs.</li><li><code>OAUTH21_BOOTSTRAP=1</code> — opt-in for real ceremonies. Sub-Issue #865 wires <code>oauth2-mock-server</code> through testcontainers behind this gate.</li><li>Without <code>OAUTH21_BOOTSTRAP=1</code>, the real adapter&#39;s <code>discovery()</code> still returns a valid metadata document (static shape derived from <code>issuer</code>); every other method reports <code>KIWA_OAUTH21_ENV_MISSING</code>.</li></ul><h2 id="known-follow-ups" tabindex="-1">Known follow-ups <a class="header-anchor" href="#known-follow-ups" aria-label="Permalink to &quot;Known follow-ups&quot;">​</a></h2><ul><li>Sub-Issue #865 (<code>pkce-flow</code>) — real <code>oauth2-mock-server</code> via testcontainers + PKCE verifier / challenge / S256 fidelity axes.</li><li>Sub-Issue #866 (<code>dpop-refresh-rotation</code>) — DPoP proof binding + refresh token rotation with re-use detection.</li><li>Sub-Issue #867 (<code>revocation-fidelity-release-gate</code>) — Revocation cascade + real vs mock fidelity harness (5 endpoints × 4 axes = 20 comparison points) + release gate 7-axis integrated report.</li></ul>',11)])])}const v=t(i,[["render",s]]);export{u as __pageData,v as default};
